target.css:
:root {
  --ink: #24372f;
  --muted: #68776e;
  --paper: #fffdf7;
  --sage: #dce8d7;
  --sage-deep: #5f8068;
  --seafoam: #b9d9ce;
  --sand: #f1dfb9;
  --line: #c9d6c8;
}

.cure-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line);
}

.studio-mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 11px;
  background: var(--seafoam);
  font-size: 19px;
}

.heading-copy {
  flex: 1;
}

.eyebrow,
.batch-label,
.description {
  margin: 0;
}

.eyebrow,
.batch-label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.heading-copy h1 {
  margin: 2px 0 0;
  font-size: 18px;
  line-height: 1.1;
}

.status-badge {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--sage);
  color: var(--sage-deep);
  font-size: 12px;
  font-weight: 700;
}

.batch-content {
  display: grid;
  grid-template-columns: 116px 1fr;
  gap: 16px;
  padding: 15px 16px;
}

.soap-bars {
  display: flex;
  align-items: end;
  justify-content: center;
  gap: 5px;
  margin: 0;
  padding: 12px 8px;
  border-radius: 13px;
  background: var(--sage);
}

.soap-bars span {
  display: block;
  width: 23px;
  height: 54px;
  border: 1px solid var(--sage-deep);
  border-radius: 7px 7px 10px 10px;
  background: var(--sand);
}

.soap-bars span:nth-child(2) {
  height: 62px;
  background: var(--seafoam);
}

.batch-notes {
  min-width: 0;
  padding-top: 3px;
}

.description {
  margin-top: 5px;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.3;
}

.meta-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 13px 0 0;
  padding: 0;
  list-style: none;
}

.meta-list li {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.meta-list strong {
  font-size: 14px;
  line-height: 1;
}

.meta-list span {
  color: var(--muted);
  font-size: 11px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  background: var(--sage);
  color: var(--muted);
  font-size: 12px;
}

.card-footer strong {
  color: var(--ink);
}

.card-footer button {
  border: 0;
  border-radius: 8px;
  padding: 7px 10px;
  background: var(--sage-deep);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

